const updateTask = `-- name: UpdateTask :one
UPDATE tasks SET
    title       = COALESCE($1, title),
    description = COALESCE($2, description),
    priority    = COALESCE($3, priority),
    assignee_id = CASE WHEN $4::bool THEN $5 ELSE assignee_id END,
    assignment_group_id = CASE WHEN $6::bool THEN $7
                               ELSE assignment_group_id END,
    -- The whole object: the save works out the fields from the form and writes the result.
    fields      = COALESCE($8::jsonb, fields)
WHERE id = $9
RETURNING id, number, title, description, status, priority, requester_id, assignee_id, created_at, updated_at, state_category, type, assignment_group_id, fields, parent_id
`

type UpdateTaskParams struct {
	Title              pgtype.Text   `json:"title"`
	Description        pgtype.Text   `json:"description"`
	Priority           pgtype.Int2   `json:"priority"`
	SetAssignee        bool          `json:"set_assignee"`
	AssigneeID         uuid.NullUUID `json:"assignee_id"`
	SetAssignmentGroup bool          `json:"set_assignment_group"`
	AssignmentGroupID  uuid.NullUUID `json:"assignment_group_id"`
	Fields             []byte        `json:"fields"`
	ID                 uuid.UUID     `json:"id"`
}

func (q *Queries) UpdateTask(ctx context.Context, arg UpdateTaskParams) (Task, error) {
	row := q.db.QueryRow(ctx, updateTask,
		arg.Title,
		arg.Description,
		arg.Priority,
		arg.SetAssignee,
		arg.AssigneeID,
		arg.SetAssignmentGroup,
		arg.AssignmentGroupID,
		arg.Fields,
		arg.ID,
	)
	var i Task
	err := row.Scan(
		&i.ID,
		&i.Number,
		&i.Title,
		&i.Description,
		&i.Status,
		&i.Priority,
		&i.RequesterID,
		&i.AssigneeID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.StateCategory,
		&i.Type,
		&i.AssignmentGroupID,
		&i.Fields,
		&i.ParentID,
	)
	return i, err
}

